-- Mixed-type comparisons with Decimal512. 26.8 compares two different types through DecimalComparison::applyMixed;
-- Decimal512 keeps the fused kernel there, which decides a scaled operand outside Int512, the scale multiplier 10^154 and
-- a UInt512 operand above Int512 exactly, with and without decimal_check_overflow, for constant and column operands.
-- Columns: less, equals, greater. The reference is exact rational arithmetic.
-- m80154: 10000 * 10^150 = 10^154 leaves Int512
SELECT less(CAST('0.5' AS Decimal(154, 150)), toInt64('10000')), equals(CAST('0.5' AS Decimal(154, 150)), toInt64('10000')), greater(CAST('0.5' AS Decimal(154, 150)), toInt64('10000')) SETTINGS decimal_check_overflow = 1;
SELECT less(materialize(CAST('0.5' AS Decimal(154, 150))), toInt64('10000')), equals(materialize(CAST('0.5' AS Decimal(154, 150))), toInt64('10000')), greater(materialize(CAST('0.5' AS Decimal(154, 150))), toInt64('10000')) SETTINGS decimal_check_overflow = 1;
SELECT less(CAST('0.5' AS Decimal(154, 150)), materialize(toInt64('10000'))), equals(CAST('0.5' AS Decimal(154, 150)), materialize(toInt64('10000'))), greater(CAST('0.5' AS Decimal(154, 150)), materialize(toInt64('10000'))) SETTINGS decimal_check_overflow = 1;
